// Pending OutboundQueue rows that are due, inside calling hours, capped per run.
// Rows that can never be dialled are marked so they don't come back every hour.
const tz = $env.BUSINESS_TIMEZONE || 'Asia/Kolkata';
const startHour = Number($env.OUTBOUND_START_HOUR || 10);
const endHour = Number($env.OUTBOUND_END_HOUR || 20);   // last call starts before this hour
const maxPerRun = Number($env.OUTBOUND_MAX_PER_RUN) > 0 ? Number($env.OUTBOUND_MAX_PER_RUN) : 20;

const hour = Number(new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', hourCycle: 'h23' }).format(new Date()));
if (hour < startHour || hour >= endHour) return [];

const now = Date.now();
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.row_number || String(r.status || '').trim().toLowerCase() !== 'pending') continue;
  const phone = String(r.phone || '').replace(/[\s()-]/g, '');
  const when = String(r.scheduled_time || '').trim();
  const due = when === '' ? now : Date.parse(when);
  const base = {
    row_number: r.row_number, phone, name: String(r.name || '').trim(), purpose: String(r.purpose || 'follow_up').trim(),
    language_pref: String(r.language_pref || 'en').trim(), business_id: String(r.business_id || 'default').trim()
  };
  if (!/^\+[1-9]\d{7,14}$/.test(phone)) out.push({ ...base, outcome: 'invalid_phone' });
  else if (Number.isNaN(due)) out.push({ ...base, outcome: 'invalid_schedule' });
  else if (due <= now) out.push({ ...base, outcome: 'dial' });
}

const dial = out.filter(c => c.outcome === 'dial').slice(0, maxPerRun);
const invalid = out.filter(c => c.outcome !== 'dial');
return [...dial, ...invalid].map(json => ({ json }));

// Don't call a guest whom staff are handling (active row in Handoffs). If the Handoffs sheet
// can't be read, dial nobody this run: the queue is retried next hour, a wrong call can't be undone.
const handoffs = $input.all().map(i => i.json);
if (handoffs.some(h => h.error)) return [];

const now = Date.now();
const paused = new Set(handoffs
  .filter(h => String(h.status || '').trim().toLowerCase() === 'active')
  .filter(h => { const t = Date.parse(String(h.paused_until || '')); return Number.isNaN(t) || t > now; })
  .map(h => String(h.handoff_key || '')));

const base = String($env.N8N_BASE_URL || '').trim().replace(/\/+$/, '');
const q = obj => Object.entries(obj).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');

return $('Select Due Calls').all().map(({ json: c }) => {
  const key = `${c.business_id}:${c.phone.replace(/\D/g, '')}`;
  let outcome = c.outcome;
  if (outcome === 'dial' && paused.has(key)) outcome = 'skipped_handoff';
  if (outcome === 'dial' && !base) outcome = 'base_url_not_configured';
  return { json: {
    ...c,
    outcome,
    queue_status: outcome === 'dial' ? 'dialing' : outcome,
    // Query order and encoding must match what the signature check rebuilds
    greeting_url: `${base}/webhook/voice/outbound-greeting?${q({ row: c.row_number, biz: c.business_id, purpose: c.purpose, lang: c.language_pref, name: c.name })}`,
    status_url: `${base}/webhook/voice/outbound-status?${q({ row: c.row_number })}`
  } };
});

// Twilio answers a created call with its sid; anything else is a failed attempt.
const call = $('Dial?').item.json;
const res = $json;
const ok = typeof res.sid === 'string' && res.sid.startsWith('CA');
return { json: {
  row_number: call.row_number,
  queue_status: ok ? 'calling' : 'dial_failed',
  call_sid: ok ? res.sid : '',
  error: ok ? '' : String(res.error ? (res.error.message || JSON.stringify(res.error)) : 'no call sid').slice(0, 300)
} };

// Reject requests that did not come from Twilio before any call logic runs.
// Twilio signs: full request URL + every POST param sorted by name (name + value),
// HMAC-SHA1 with the account auth token, base64. The URL is rebuilt from N8N_BASE_URL,
// the same base the TwiML action URLs use, so it matches what Twilio requested.
// TWILIO_SIGNATURE_MODE: enforce (default) = reject | log = let through, flagged | off = skip.
// Needs the 'crypto' built-in: N8N_RUNNERS_ALLOWED_BUILT_IN_MODULES=crypto (legacy: NODE_FUNCTION_ALLOW_BUILTIN).
const WEBHOOK_PATH = '/webhook/voice/outbound-greeting';
const req = $input.first().json;
const mode = String($env.TWILIO_SIGNATURE_MODE || 'enforce').trim().toLowerCase();
const token = String($env.TWILIO_AUTH_TOKEN || '');
const base = String($env.N8N_BASE_URL || '').trim().replace(/\/+$/, '');
const query = req.query || {};
const qs = Object.keys(query)
  .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(query[k])}`)
  .join('&');
const url = base + WEBHOOK_PATH + (qs ? `?${qs}` : '');
const provided = String((req.headers || {})['x-twilio-signature'] || '');

let crypto = null;
try { crypto = require('crypto'); } catch (e) { crypto = null; }

let valid = false;
let reason = 'ok';
if (mode === 'off') reason = 'check_disabled';
else if (!token) reason = 'auth_token_not_configured';
else if (!base) reason = 'base_url_not_configured';
else if (!provided) reason = 'missing_signature_header';
else if (!crypto) reason = 'crypto_module_not_allowed';
else {
  const body = req.body || {};
  const payload = url + Object.keys(body).sort()
    .map(k => [].concat(body[k] ?? '').slice().sort().map(v => k + v).join(''))
    .join('');
  const expected = Buffer.from(crypto.createHmac('sha1', token).update(payload, 'utf8').digest('base64'));
  const got = Buffer.from(provided);
  valid = expected.length === got.length && crypto.timingSafeEqual(expected, got);
  if (!valid) reason = 'signature_mismatch';
}

return [{ json: {
  ...req,
  signature_valid: valid,
  signature_reason: reason,
  signature_url: url,
  request_allowed: valid || mode === 'off' || mode === 'log'
} }];

// Twilio fetches this when the guest picks up. A voicemail gets a short message; a person gets
// the purpose greeting, then the normal call loop (voice/turn in the call handler) takes over.
const req = $input.first().json;
const q = req.query || {};
const b = req.body || {};
const clean = t => String(t || '').replace(/[&<>"']/g, '').slice(0, 60);
const name = clean(q.name);
const hi = name ? `Hi ${name}!` : 'Hi!';
const venue = clean($env.BUSINESS_NAME) || 'the venue';
const answeredBy = String(b.AnsweredBy || '');
const voicemail = answeredBy.startsWith('machine_') || answeredBy === 'fax';

const base = String($env.N8N_BASE_URL || 'https://YOUR_N8N_URL').trim().replace(/\/+$/, '');
const turnUrl = `${base}/webhook/voice/turn?sid=${encodeURIComponent(b.CallSid || '')}&amp;biz=${encodeURIComponent(q.biz || 'default')}`;

const templates = {
  booking_reminder: `${hi} This is Priya from ${venue}. I'm calling to confirm your reservation. Do you have a quick moment?`,
  follow_up: `${hi} This is Priya from ${venue}. You enquired with us recently, and I wanted to check if you'd like to go ahead with a booking?`,
  event_promo: `${hi} This is Priya from ${venue}. We have an exciting event coming up and I thought of you. Do you have a minute?`,
  feedback: `${hi} This is Priya from ${venue}. You visited us recently and we'd love your quick feedback. Do you have two minutes?`,
  offer: `${hi} This is Priya from ${venue}. We have an exclusive offer for our regular guests. Can I share the details?`
};
const purpose = templates[q.purpose] ? q.purpose : 'follow_up';

const twiml = voicemail
  ? `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">${hi} This is Priya from ${venue}. Sorry we missed you. Please call us back when it suits you. Thank you!</Say>
  <Hangup/>
</Response>`
  : `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">${templates[purpose]}</Say>
  <Record maxLength="15" timeout="4" playBeep="false" transcribe="false"
    action="${turnUrl}" />
  <Say voice="Polly.Aditi" language="en-IN">I am still here if you need anything.</Say>
  <Record maxLength="15" timeout="5" playBeep="false" transcribe="false"
    action="${turnUrl}" />
</Response>`;

return [{ json: { twiml_response: twiml, voicemail, purpose, row_number: q.row || '' } }];

// Reject requests that did not come from Twilio before any call logic runs.
// Twilio signs: full request URL + every POST param sorted by name (name + value),
// HMAC-SHA1 with the account auth token, base64. The URL is rebuilt from N8N_BASE_URL,
// the same base the TwiML action URLs use, so it matches what Twilio requested.
// TWILIO_SIGNATURE_MODE: enforce (default) = reject | log = let through, flagged | off = skip.
// Needs the 'crypto' built-in: N8N_RUNNERS_ALLOWED_BUILT_IN_MODULES=crypto (legacy: NODE_FUNCTION_ALLOW_BUILTIN).
const WEBHOOK_PATH = '/webhook/voice/outbound-status';
const req = $input.first().json;
const mode = String($env.TWILIO_SIGNATURE_MODE || 'enforce').trim().toLowerCase();
const token = String($env.TWILIO_AUTH_TOKEN || '');
const base = String($env.N8N_BASE_URL || '').trim().replace(/\/+$/, '');
const query = req.query || {};
const qs = Object.keys(query)
  .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(query[k])}`)
  .join('&');
const url = base + WEBHOOK_PATH + (qs ? `?${qs}` : '');
const provided = String((req.headers || {})['x-twilio-signature'] || '');

let crypto = null;
try { crypto = require('crypto'); } catch (e) { crypto = null; }

let valid = false;
let reason = 'ok';
if (mode === 'off') reason = 'check_disabled';
else if (!token) reason = 'auth_token_not_configured';
else if (!base) reason = 'base_url_not_configured';
else if (!provided) reason = 'missing_signature_header';
else if (!crypto) reason = 'crypto_module_not_allowed';
else {
  const body = req.body || {};
  const payload = url + Object.keys(body).sort()
    .map(k => [].concat(body[k] ?? '').slice().sort().map(v => k + v).join(''))
    .join('');
  const expected = Buffer.from(crypto.createHmac('sha1', token).update(payload, 'utf8').digest('base64'));
  const got = Buffer.from(provided);
  valid = expected.length === got.length && crypto.timingSafeEqual(expected, got);
  if (!valid) reason = 'signature_mismatch';
}

return [{ json: {
  ...req,
  signature_valid: valid,
  signature_reason: reason,
  signature_url: url,
  request_allowed: valid || mode === 'off' || mode === 'log'
} }];

// Twilio's final status for an outbound call -> the queue row's result.
const req = $('Signature OK? (Status)').first().json;
const b = req.body || {};
const row = parseInt((req.query || {}).row, 10);
if (!(row > 1)) return [];   // row 1 is the header; anything else isn't one of our calls

const status = String(b.CallStatus || '').toLowerCase();
const machine = String(b.AnsweredBy || '').startsWith('machine_');
const result = status === 'completed' ? (machine ? 'voicemail' : 'completed')
  : ['busy', 'no-answer', 'failed', 'canceled'].includes(status) ? status : (status || 'unknown');

return [{ json: { row_number: row, queue_status: result, call_sid: b.CallSid || '', call_duration: b.CallDuration || '' } }];
